#include <Common/EngineEnvironment.h>
#include <gtest/gtest.h>

/**
 * The icons: `assets/icons/icons.png` is generated by `tools/make_icons.py` and the `Icon_` sprites of `config/TextureLibrary.xml` by
 * `tools/make_tiles.py` from the script's list; both are read here from the source tree (a game's content is not mounted in the test
 * environment). The PNG is checked by its header (zlib is not linked into the tests; the pixels are checked by
 * `python3 tools/make_icons.py --check`), the XML by its sprites against the numbers of the script, copied below: **change both together**.
 */
namespace BECore::Mahjong::Tests {

    using namespace BECore::Tests;

    namespace {

        constexpr size_t kPngSignatureSize = 8;
        constexpr size_t kIhdrDataOffset = kPngSignatureSize + 8;  // after the signature, the chunk length and the chunk type
        constexpr size_t kIhdrSize = 13;
        constexpr size_t kIhdrTypeOffset = kPngSignatureSize + 4;  // the chunk type follows the 4 bytes of the chunk length
        constexpr size_t kIhdrHeightOffset = 4;                    // within the chunk data: width (4), height (4), depth, colour type, ...
        constexpr size_t kIhdrDepthOffset = 8;
        constexpr size_t kIhdrColorTypeOffset = 9;
        constexpr size_t kIhdrInterlaceOffset = 12;
        constexpr uint8_t kBitDepth = 8;
        constexpr uint8_t kColorTypeRgba = 6;
        constexpr uint8_t kNoInterlace = 0;
        constexpr unsigned char kPngSignature[kPngSignatureSize] = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1A, '\n'};

        // tools/make_icons.py: CELL, COLUMNS, ROWS, ICON_NAMES, TEXTURE_PATH
        constexpr int kIconCellSize = 64;
        constexpr int kIconColumns = 4;
        constexpr int kIconRows = 2;
        constexpr int kIconAtlasWidth = kIconCellSize * kIconColumns;
        constexpr int kIconAtlasHeight = kIconCellSize * kIconRows;
        constexpr const char* kIconAtlasPath = "assets/icons/icons.png";
        constexpr eastl::string_view kIconSpritePrefix = "Icon_";
        constexpr const char* kIconNames[] = {"Icon_Rules", "Icon_Options", "Icon_NewGame", "Icon_Leave", "Icon_Close", "Icon_Back", "Icon_Next", "Icon_Hint"};
        constexpr size_t kIconCount = sizeof(kIconNames) / sizeof(kIconNames[0]);

        std::filesystem::path GameRoot() {
            return std::filesystem::path(__FILE__).parent_path().parent_path();
        }

        uint32_t ReadBigEndian(const std::vector<unsigned char>& bytes, size_t offset) {
            return (static_cast<uint32_t>(bytes[offset]) << 24) | (static_cast<uint32_t>(bytes[offset + 1]) << 16) | (static_cast<uint32_t>(bytes[offset + 2]) << 8) |
                   static_cast<uint32_t>(bytes[offset + 3]);
        }

        struct Sprite {
            eastl::string name;
            eastl::string texturePath;
            Rect rect;
        };

        bool Overlap(const Rect& a, const Rect& b) {
            return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
        }

    }  // namespace

    class IconSpritesTest : public ::testing::Test {
    protected:
        static void SetUpTestSuite() {
            EngineEnvironment::EnsureCoreServices();
        }

        void SetUp() override {
            const std::filesystem::path xmlPath = GameRoot() / "config" / "TextureLibrary.xml";
            const XmlConfig config = XmlConfig::Create();
            ASSERT_TRUE(config.LoadFromFile(xmlPath)) << xmlPath.string();
            const XmlNode sprites = config.GetRoot().GetChild("sprites");
            ASSERT_TRUE(static_cast<bool>(sprites));
            for (const XmlNode node : sprites.Children()) {
                if (node.Name() != eastl::string_view("sprite")) {
                    continue;
                }
                Sprite sprite;
                sprite.name = eastl::string(node.GetAttribute("name").value_or(""));
                if (sprite.name.compare(0, kIconSpritePrefix.size(), kIconSpritePrefix.data()) != 0) {
                    continue;  // the tiles are TileSpritesTest's
                }
                sprite.texturePath = eastl::string(node.GetAttribute("texturePath").value_or(""));
                const XmlNode source = node.GetChild("srcRect");
                ASSERT_TRUE(static_cast<bool>(source)) << sprite.name.c_str();
                sprite.rect = Rect(source.ParseAttribute<float>("x").value_or(-1.0f), source.ParseAttribute<float>("y").value_or(-1.0f), source.ParseAttribute<float>("w").value_or(-1.0f),
                                   source.ParseAttribute<float>("h").value_or(-1.0f));
                _sprites.push_back(sprite);
            }
        }

        eastl::vector<Sprite> _sprites;
    };

    TEST_F(IconSpritesTest, ThePngIsAnRgbaPictureOfTheAtlasSize) {
        const std::filesystem::path pngPath = GameRoot() / kIconAtlasPath;
        std::ifstream file(pngPath, std::ios::binary);
        ASSERT_TRUE(file.is_open()) << pngPath.string();
        std::vector<unsigned char> head(kIhdrDataOffset + kIhdrSize);
        file.read(reinterpret_cast<char*>(head.data()), static_cast<std::streamsize>(head.size()));
        ASSERT_EQ(static_cast<size_t>(file.gcount()), head.size());
        EXPECT_TRUE(std::equal(std::begin(kPngSignature), std::end(kPngSignature), head.begin()));
        EXPECT_EQ(std::string(head.begin() + kIhdrTypeOffset, head.begin() + kIhdrDataOffset), "IHDR");
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset), static_cast<uint32_t>(kIconAtlasWidth));
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset + kIhdrHeightOffset), static_cast<uint32_t>(kIconAtlasHeight));
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrDepthOffset], kBitDepth);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrColorTypeOffset], kColorTypeRgba);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrInterlaceOffset], kNoInterlace);
    }

    TEST_F(IconSpritesTest, TheLibraryHoldsOneSpritePerIconInTheOrderOfTheScript) {
        ASSERT_EQ(_sprites.size(), kIconCount);
        for (size_t index = 0; index < kIconCount; ++index) {
            const Sprite& sprite = _sprites[index];
            EXPECT_EQ(sprite.name, eastl::string(kIconNames[index]));
            EXPECT_EQ(sprite.texturePath, eastl::string(kIconAtlasPath)) << sprite.name.c_str();
            const int column = static_cast<int>(index) % kIconColumns;
            const int row = static_cast<int>(index) / kIconColumns;
            EXPECT_EQ(sprite.rect.x, static_cast<float>(column * kIconCellSize)) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.y, static_cast<float>(row * kIconCellSize)) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.w, static_cast<float>(kIconCellSize)) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.h, static_cast<float>(kIconCellSize)) << sprite.name.c_str();
        }
    }

    TEST_F(IconSpritesTest, EveryRectLiesInsideTheImageAndNoTwoOverlap) {
        for (size_t first = 0; first < _sprites.size(); ++first) {
            const Rect& rect = _sprites[first].rect;
            EXPECT_GE(rect.x, 0.0f) << _sprites[first].name.c_str();
            EXPECT_GE(rect.y, 0.0f) << _sprites[first].name.c_str();
            EXPECT_LE(rect.x + rect.w, static_cast<float>(kIconAtlasWidth)) << _sprites[first].name.c_str();
            EXPECT_LE(rect.y + rect.h, static_cast<float>(kIconAtlasHeight)) << _sprites[first].name.c_str();
            for (size_t second = first + 1; second < _sprites.size(); ++second) {
                EXPECT_NE(_sprites[first].name, _sprites[second].name);
                EXPECT_FALSE(Overlap(rect, _sprites[second].rect)) << _sprites[first].name.c_str() << " and " << _sprites[second].name.c_str();
            }
        }
    }

}  // namespace BECore::Mahjong::Tests
